<script>
(function(){
  const C1=[[-0.11,1.68],[0.68,2.39],[1.29,1.52],[1.54,2.71],[2.18,1.94],
             [0.91,1.14],[1.82,2.55],[0.42,2.10],[1.66,1.38],[2.37,2.13],
             [1.12,2.88],[0.75,1.81],[1.41,2.02],[2.09,1.59],[0.58,2.44],
