    const axLen=Math.min(SCW,SCH)*0.48;
    const axX1=ctrX-Math.cos(ang)*axLen, axY1=ctrY+Math.sin(ang)*axLen;
    const axX2=ctrX+Math.cos(ang)*axLen, axY2=ctrY-Math.sin(ang)*axLen;
    ctx.strokeStyle='#16a34a'; ctx.lineWidth=2.2;
