    const Jcolor=ratio>0.85?'#16a34a':ratio>0.5?'#ca8a04':'#dc2626';
    document.getElementById('lda-jval').innerHTML=
      `J(w) = <strong style="color:${Jcolor}">${J.toFixed(3)}</strong>`+
      `&ensp;|&ensp;J<sub>opt</sub> = <strong>${Jopt.toFixed(3)}</strong>`+
      `&ensp;|&ensp;Efficiency = <strong style="color:${Jcolor}">${(ratio*100).toFixed(1)}%</strong>`+
      `&ensp;|&ensp;θ = ${curAng}°&ensp;(θ<sub>opt</sub> = ${optAngle}°)`;
